arguments.new_str:
using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZIP now sets the UTF-8 language encoding flag (EFS)
        // for non-ASCII entry names. Legacy Java consumer expects Shift-JIS, so specify
        // the encoding explicitly to prevent the EFS flag from being set.
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create,
            Encoding.GetEncoding("shift_jis"));
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9 breaking change: keyed service validation now throws at startup
// if [FromKeyedServices("cache")] resolves against a non-keyed registration.
services.AddKeyedSingleton<ICache, RedisCache>("cache");

